package org.zhixiaoce.aperture;
import java.nio.file.*;
import java.util.*;
import org.json.*;

public final class ResourcePackTest {
    static int count;interface Work{void run()throws Exception;}
    static void check(boolean value,String why){count++;if(!value)throw new AssertionError(why);}
    static void reject(Work action,String why)throws Exception{boolean failed=false;try{action.run();}catch(Exception expected){failed=true;}check(failed,why);}
    static JSONObject copy(JSONObject o)throws Exception{return new JSONObject(o.toString());}
    public static void main(String[] args)throws Exception{
        String raw=Files.readString(Path.of(args[0]));JSONObject data=new JSONObject(raw);CinemaCatalog.Config config=CinemaCatalog.config(raw,null,false);
        check(config.packId.equals("org.example.family")&&config.packRevision==1,"pack metadata");check(config.sites.size()==4&&config.lives.size()==1,"one file imports five heterogeneous resources");
        check(config.packSha256.equals(CinemaResourcePack.sha256(raw)),"exact original UTF8 hash");check(config.lives.get(0).key().equals("kaishi:org.example.family:live")&&config.lives.get(0).channels.get(0).id.equals("living-room"),"stable live/source identities");
        CinemaCatalog.Config saved=CinemaCatalog.config(config.json(),null,false);check(saved.packSha256.equals(config.packSha256)&&saved.sites.get(2).items.length()==1,"encrypted-storage serialization round trip");check(saved.lives.get(0).channels.get(0).id.equals("living-room"),"channel IDs survive normalized storage");
        CinemaCatalog.Site variety=saved.sites.get(2);check(variety.supports("variety")&&!variety.supports("movies"),"variety separated from movies");CinemaHttp http=new CinemaHttp();CinemaCatalog.Page home=http.home(variety,false);check(home.categories.get(0).id.equals("variety"),"native home routes inline collection without network");
        CinemaCatalog.Page detail=http.catalogue(variety,null,1,null,"family-show",false);check(detail.items.size()==1&&detail.items.get(0).name.equals("家庭舞台"),"inline detail retains stable item ID");check(CinemaCatalog.lines(detail.items.get(0),false).get(0).episodes.size()==2,"structured episodes reach production player lines");
        check(http.catalogue(variety,null,1,"家庭",null,false).items.size()==1&&http.catalogue(variety,null,1,"不存在",null,false).items.isEmpty(),"Unicode search and honest empty result");
        CinemaCatalog.Page upstream=CinemaCatalog.page("{\"class\":[{\"type_id\":\"3\",\"type_name\":\"频道三\"},{\"type_id\":\"1\",\"type_name\":\"电影\"}]}",1);check(CinemaResourcePack.categories(saved.sites.get(3),upstream,"variety").size()==1,"explicit upstream category IDs select variety");
        check(CinemaResourcePack.matches("variety","真人秀")&&!CinemaResourcePack.matches("variety","电视剧"),"legacy category matching");
        check(!CinemaResourcePack.shouldApply(saved,config),"same bytes and revision are an idempotent no-op");check(CinemaResourcePack.shouldApply(saved,CinemaCatalog.config(raw,null,true)),"an explicit local HTTP policy change is applied even for identical bytes");JSONObject changed=copy(data).put("title","新版标题");CinemaCatalog.Config conflicting=CinemaCatalog.config(changed.toString(),null,false);reject(()->CinemaResourcePack.shouldApply(saved,conflicting),"same revision different bytes is a conflict");changed.put("revision",2);CinemaCatalog.Config updated=CinemaCatalog.config(changed.toString(),null,false);check(CinemaResourcePack.shouldApply(saved,updated),"higher revision allowed");reject(()->CinemaResourcePack.shouldApply(updated,saved),"rollback rejected");
        check(updated.sites.get(2).identity.equals(variety.identity),"metadata update preserves source identity");CinemaShelf shelf=new CinemaShelf("[]");JSONObject ref=CinemaShelf.ref("vod",variety.identity,"family-show","家庭舞台","");shelf.toggle(ref,"favorite");shelf.watch(ref,"播放","第1期",9000,60000,false,1);check(shelf.resume(CinemaShelf.ref("vod",updated.sites.get(2).identity,"family-show","新标题",""),"播放","第1期")==9000,"bundle update preserves viewing state");
        for(String key:new String[]{"format","version","id","revision","title","resources"}){JSONObject missing=copy(data);missing.remove(key);reject(()->CinemaCatalog.config(missing.toString(),null,false),"required "+key);}
        reject(()->CinemaCatalog.config(copy(data).put("version",2).toString(),null,false),"unknown version");reject(()->CinemaCatalog.config(copy(data).put("unexpected",true).toString(),null,false),"unknown root field");reject(()->CinemaCatalog.config(copy(data).put("revision",1.5).toString(),null,false),"fractional revision");
        JSONObject duplicate=copy(data);duplicate.getJSONArray("resources").getJSONObject(1).put("id","live");reject(()->CinemaCatalog.config(duplicate.toString(),null,false),"duplicate resource IDs abort whole import");
        JSONObject unsupported=copy(data);unsupported.getJSONArray("resources").getJSONObject(0).put("type","wallpaper");reject(()->CinemaCatalog.config(unsupported.toString(),null,false),"unsupported capability rejected explicitly");
        for(String bad:new String[]{"file:///private","javascript:alert(1)","https://user:pass@example.invalid/a","https://example.invalid/a#secret","http://example.invalid/a"}){JSONObject altered=copy(data);altered.getJSONArray("resources").getJSONObject(4).put("url",bad);reject(()->CinemaCatalog.config(altered.toString(),null,false),"unsafe address");}
        JSONObject insecure=copy(data);insecure.getJSONArray("resources").getJSONObject(4).put("url","http://192.168.1.10/api");check(CinemaCatalog.config(insecure.toString(),null,true).sites.size()==4,"device-controlled explicit HTTP policy");
        JSONObject headers=copy(data);headers.getJSONArray("resources").getJSONObject(0).put("headers",new JSONObject().put("Authorization","Bearer private"));reject(()->CinemaCatalog.config(headers.toString(),null,false),"native standard forbids credential headers");
        JSONObject episode=copy(data);JSONObject item=episode.getJSONArray("resources").getJSONObject(3).getJSONArray("items").getJSONObject(0);item.getJSONArray("episodes").getJSONObject(1).put("title","第1期");reject(()->CinemaCatalog.config(episode.toString(),null,false),"duplicate episode titles rejected");
        JSONObject symbols=copy(data);symbols.getJSONArray("resources").getJSONObject(3).getJSONArray("items").getJSONObject(0).getJSONArray("episodes").getJSONObject(0).put("title","第1期 # $ 特别篇");CinemaCatalog.Config symbolConfig=CinemaCatalog.config(symbols.toString(),null,false);check(CinemaCatalog.lines(http.catalogue(symbolConfig.sites.get(2),null,1,null,"family-show",false).items.get(0),false).get(0).episodes.get(0).name.equals("第1期 # $ 特别篇"),"structured standard does not inherit TVBox delimiter escaping");
        JSONObject tooMany=copy(data);JSONArray resources=tooMany.getJSONArray("resources");for(int i=0;i<9;i++)resources.put(copy(resources.getJSONObject(4)).put("id","extra-"+i));reject(()->CinemaCatalog.config(tooMany.toString(),null,false),"aggregate site limit is atomic");
        CinemaCatalog.Config legacy=CinemaCatalog.config(Files.readString(Path.of(args[1])),null,false);check(legacy.sites.get(0).supports("variety")&&!legacy.sites.get(0).supports("movies"),"TVBox adapter section mapping");
        JSONObject emptyParsers=new JSONObject(Files.readString(Path.of(args[1])));emptyParsers.getJSONArray("resources").getJSONObject(0).getJSONObject("config").put("parses",new JSONArray());check(CinemaCatalog.config(emptyParsers.toString(),null,false).sites.size()==1,"empty legacy parser list does not block supported resources");
        JSONObject nested=new JSONObject(Files.readString(Path.of(args[1])));nested.getJSONArray("resources").getJSONObject(0).put("config",data);reject(()->CinemaCatalog.config(nested.toString(),null,false),"nested packs rejected");
        System.out.println("Resource packs: "+count+" assertions passed; no Android runtime or media decoding claim");
    }
}
